// @generated by:gauntlet run:godseye-local-coding-runners
import { createHash, randomUUID } from "node:crypto";
import {
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  type CodingOverviewView,
  type CodingTaskDetailView,
  type ProjectDTO,
} from "@godseye/contracts";
import { expect, test } from "@playwright/test";
import { enrollConsoleOwner } from "./owner-fixture.js";

test.beforeEach(async ({ page, baseURL }, testInfo) => {
  await enrollConsoleOwner(page, baseURL, testInfo.project.metadata);
});

for (const [layout, width, height] of [
  ["desktop", 1440, 1000],
  ["mobile", 390, 844],
] as const) {
  test(`T-AC-793 ${layout} owner prepares exact scope while unavailable and downloads inert fixture evidence`, async ({
    page,
  }, testInfo) => {
    await page.setViewportSize({ width, height });
    await page.goto("/hermes?vue=code");
    // Project/auth/binding and preparation use actual owner HTTP. Only completed
    // execution/result reads below are labeled UI fixtures, never native proof.
    const project = (await page.evaluate(
      async (suffix) => {
        const headers = {
          "content-type": "application/json",
          "idempotency-key": crypto.randomUUID(),
        };
        const created = await fetch("/api/v1/projects", {
          method: "POST",
          headers,
          body: JSON.stringify({
            name: `Coding ${suffix}`,
            slug: `coding-${suffix}`,
            kind: "web",
            description: "Synthetic browser project",
          }),
        });
        const value = await created.json();
        const bound = await fetch(`/api/v1/projects/${value.id}/repository`, {
          method: "PUT",
          headers: { ...headers, "idempotency-key": crypto.randomUUID() },
          body: JSON.stringify({
            expectedRevision: value.revision,
            repository: {
              fullName: "fixture/coding",
              repositoryId: 12345,
              installationId: 67890,
              branch: "main",
              autoDeploy: false,
            },
          }),
        });
        if (!bound.ok) throw new Error(`Fixture binding failed ${bound.status}`);
        return bound.json();
      },
      randomUUID().slice(0, 8),
    )) as ProjectDTO;
    await page.reload();
    const panel = page.getByRole("region", { name: "Tâches de code isolées" });
    await expect(panel.getByText(/Indisponible/).first()).toBeVisible();
    await panel
      .getByRole("combobox", { name: "Projet de code", exact: true })
      .selectOption(project.id);
    const environment = project.environments.find((value) => value.kind === "development");
    if (!environment) throw new Error("Missing browser coding environment");
    await panel
      .getByRole("combobox", { name: "Environnement de code", exact: true })
      .selectOption(environment.id);
    await panel.getByLabel("Commit exact", { exact: true }).fill("a".repeat(40));
    const intent = `Synthetic exact repository change ${layout}`;
    await panel.getByRole("textbox", { name: "Demande", exact: true }).fill(intent);
    await expect(panel.getByLabel("Budget maximal réservé (USD)", { exact: true })).toHaveValue(
      "0.5",
    );
    await panel.getByRole("button", { name: "Préparer la tâche", exact: true }).click();
    const preparedCard = panel
      .getByRole("article")
      .filter({ has: page.getByText(intent, { exact: true }) });
    await expect(preparedCard).toBeVisible();
    await expect(
      preparedCard.getByRole("button", { name: "Lancer cette préparation", exact: true }),
    ).toBeDisabled();
    const source = (await page.evaluate(async () =>
      (await fetch("/api/v1/agents/coding")).json(),
    )) as CodingOverviewView;
    const preparation = source.preparations.find((value) => value.projectId === project.id);
    if (!preparation) throw new Error("Actual browser preparation missing");
    expect(preparation.limits.maxCostMicros).toBe(500000);
    const runnerChoice = panel.getByRole("combobox", { name: "Runner", exact: true });
    const budgetChoice = panel.getByLabel("Budget maximal réservé (USD)", { exact: true });
    await runnerChoice.selectOption("claude-code");
    await expect(budgetChoice).toHaveValue("0.1");
    await runnerChoice.selectOption("codex");
    await expect(budgetChoice).toHaveValue("0.5");
    await budgetChoice.fill("0.07");
    await runnerChoice.selectOption("claude-code");
    await expect(budgetChoice).toHaveValue("0.07");
    await runnerChoice.selectOption("codex");
    await expect(budgetChoice).toHaveValue("0.07");
    const patch = "<script>window.__codingExecuted=true</script>\n+évidence\n";
    const log = "Synthetic observed fixture log\n<script>window.__codingExecuted=true</script>\n";
    const artifact = (kind: "patch" | "test-log", content: string) => ({
      id: randomUUID(),
      kind,
      content,
      bytes: Buffer.byteLength(content),
      sha256: createHash("sha256").update(content).digest("hex"),
    });
    const now = new Date().toISOString();
    const task = {
      id: randomUUID(),
      preparationId: preparation.id,
      projectId: project.id,
      environmentId: environment.id,
      runId: randomUUID(),
      runner: preparation.runner,
      state: "failed" as const,
      correlationId: randomUUID(),
      submissionIntended: true,
      cleanupState: "stopped" as const,
      worktree: {
        id: randomUUID(),
        baseSha: preparation.commitSha,
        disposition: "retained" as const,
      },
      reason: null,
      createdAt: now,
      updatedAt: now,
      finishedAt: now,
    };
    const detail: CodingTaskDetailView = {
      task,
      preparation,
      result: {
        taskId: task.id,
        worktreeId: task.worktree.id,
        preparationHash: preparation.hash,
        commitSha: preparation.commitSha,
        summary: "Labeled synthetic UI result",
        patch: artifact("patch", patch),
        tests: [{ profile: "test", status: "failed", exitCode: 1, log: artifact("test-log", log) }],
        preview: { state: "unavailable", reason: "No preview adapter" },
        usage: { inputTokens: null, outputTokens: null, costMicros: null, accounting: "unknown" },
      },
    };
    const responseHeaders = {
      "content-type": "application/json",
      [CONTROL_API_HEADER]: CONTROL_API_VERSION,
    };
    await page.route("**/api/v1/agents/coding", (route) =>
      route.fulfill({
        status: 200,
        headers: responseHeaders,
        body: JSON.stringify({ ...source, tasks: [task] }),
      }),
    );
    await page.route(`**/api/v1/agents/coding/tasks/${task.id}`, (route) =>
      route.fulfill({ status: 200, headers: responseHeaders, body: JSON.stringify(detail) }),
    );
    await page.reload();
    await panel.getByRole("button", { name: "codex · Échec", exact: true }).click();
    await expect(panel.getByText("Labeled synthetic UI result", { exact: true })).toBeVisible();
    await panel.getByText(/^Patch ·/).click();
    await expect(panel.getByText(patch, { exact: true })).toBeVisible();
    expect(await page.evaluate(() => Reflect.get(window, "__codingExecuted"))).toBeUndefined();
    for (const [label, filename, content] of [
      ["Télécharger le patch texte", "coding-patch.txt", patch],
      ["Télécharger le journal texte", "coding-test-log.txt", log],
    ] as const) {
      const pending = page.waitForEvent("download");
      const button = panel.getByRole("button", { name: label, exact: true });
      await button.focus();
      await page.keyboard.press("Enter");
      const download = await pending;
      expect(download.suggestedFilename()).toBe(filename);
      const stream = await download.createReadStream();
      if (!stream) throw new Error("Missing inert evidence download stream");
      const chunks: Buffer[] = [];
      for await (const chunk of stream) chunks.push(Buffer.from(chunk));
      expect(Buffer.concat(chunks)).toEqual(Buffer.from(content));
    }
    const bounds = await panel.evaluate((element) => ({
      left: element.getBoundingClientRect().left,
      right: element.getBoundingClientRect().right,
      scroll: document.documentElement.scrollWidth,
      viewport: window.innerWidth,
    }));
    expect(bounds.left).toBeGreaterThanOrEqual(0);
    expect(bounds.right).toBeLessThanOrEqual(width);
    expect(bounds.scroll).toBeLessThanOrEqual(bounds.viewport);
    // Outer bounds can pass while overflow:hidden clips a descendant. Keep long
    // capability reasons, UUIDs and digest summaries readable at mobile width.
    const textBounds = await panel.locator("p, summary").evaluateAll((elements) =>
      elements.map((element) => ({
        text: element.textContent?.slice(0, 80),
        scroll: element.scrollWidth,
        width: element.clientWidth,
      })),
    );
    expect(textBounds.filter((value) => value.scroll > value.width + 1)).toEqual([]);
    await panel.scrollIntoViewIfNeeded();
    await page.screenshot({ path: testInfo.outputPath(`coding-${layout}.png`), fullPage: true });
    await testInfo.attach(`coding-${layout}-bounds`, {
      body: JSON.stringify(bounds),
      contentType: "application/json",
    });
  });
}
